/**
 * Enriquecer métricas (Processar Dados) com objetivo Meta + criativos agregados.
 */
const ctx = $('Filtrar campanhas (objetivo)').first().json ?? {};
const cliente = ctx.cliente ?? {};
const objetivoPorId = cliente.objetivos_por_campanha ?? {};

const aggItem = $('⚙️ Agregar ads por campanha').first()?.json ?? {};
const ads_por_campanha = aggItem.ads_por_campanha ?? {};

const metricsItems = $('Processar Dados').all();

const dados = metricsItems.map((m) => {
  const j = { ...m.json };
  const cid = j.campaign_id || j.meta_campaign_id || null;
  const cidStr = cid != null ? String(cid) : null;

  j.meta_campaign_id = cidStr;
  j.objetivo = cidStr ? objetivoPorId[cidStr] ?? null : null;
  j.nome_campanha = j.campanha ?? j.nome ?? 'Sem nome';
  j.nome = j.nome_campanha;
  j.criativos = cidStr && ads_por_campanha[cidStr] ? ads_por_campanha[cidStr] : [];

  return {
    json: {
      ...j,
      filtros: {
        data_inicio: ctx.body?.data_inicio,
        data_fim: ctx.body?.data_fim,
        objetivo_campanha: ctx.body?.objetivo_campanha ?? null,
      },
    },
  };
});

return dados;

const rawItems = $input.all();

const insights = rawItems.flatMap((item) => {
  const json = item.json;
  if (Array.isArray(json.data)) return json.data;
  if (json.insights?.data) return json.insights.data;
  return [json];
});

/** Rótulos legíveis para action_type da Meta (só tradução; métrica só entra se vier na API) */
function rotuloAcao(actionType) {
  const t = String(actionType || '');
  const mapa = {
    link_click: 'Cliques nos Anúncios',
    inline_link_click: 'Cliques nos Anúncios',
    outbound_click: 'Cliques de saída',
    landing_page_view: 'Visitas do Site',
    omni_landing_page_view: 'Visitas do Site',
    purchase: 'Vendas',
    'offsite_conversion.fb_pixel_purchase': 'Vendas',
    'onsite_conversion.purchase': 'Vendas',
    lead: 'Leads',
    'onsite_conversion.lead_grouped': 'Leads',
    follow: 'Novos Seguidores',
    'onsite_conversion.follow': 'Novos Seguidores',
    page_engagement: 'Engajamento na página',
    post_engagement: 'Engajamento em publicações',
    video_view: 'Visualizações de vídeo',
    'onsite_conversion.messaging_conversation_started_7d': 'Conversas no WhatsApp',
    messaging_conversation_started_7d: 'Conversas no WhatsApp',
    instagram_profile_engagement: 'Visitas ao Instagram',
    profile_visits: 'Visitas ao Instagram',
    like: 'Curtidas',
    comment: 'Comentários',
    share: 'Compartilhamentos',
    add_to_cart: 'Adições ao carrinho',
    initiate_checkout: 'Checkout iniciado',
    complete_registration: 'Cadastros completos',
  };
  if (mapa[t]) return mapa[t];
  return t
    .replace(/^offsite_conversion\./, '')
    .replace(/^onsite_conversion\./, '')
    .replace(/[._]/g, ' ')
    .replace(/\s+/g, ' ')
    .trim()
    .replace(/\b\w/g, (c) => c.toUpperCase());
}

function addMetrica(lista, vistos, item) {
  const nome = String(item.nome || '').trim();
  if (!nome) return;
  const chave = `${nome}|${item.formato || ''}`;
  if (vistos.has(chave)) return;
  vistos.add(chave);
  lista.push(item);
}

function metricasDaInsight(ins) {
  const metricas = [];
  const vistos = new Set();

  const spend = parseFloat(ins.spend || 0);
  const reach = parseInt(ins.reach || 0, 10);
  const impressions = parseInt(ins.impressions || 0, 10);
  const frequency = parseFloat(ins.frequency || 0);

  if (spend > 0) {
    addMetrica(metricas, vistos, {
      nome: 'Valor investido',
      valor: Number(spend.toFixed(2)),
      formato: 'moeda',
      origem: 'spend',
    });
  }
  if (reach > 0) {
    addMetrica(metricas, vistos, {
      nome: 'Pessoas Alcançadas',
      valor: reach,
      formato: 'numero',
      origem: 'reach',
    });
  }
  if (impressions > 0) {
    addMetrica(metricas, vistos, {
      nome: 'Impressões',
      valor: impressions,
      formato: 'numero',
      origem: 'impressions',
    });
  }
  if (frequency > 0) {
    addMetrica(metricas, vistos, {
      nome: 'Frequência',
      valor: Number(frequency.toFixed(2)),
      formato: 'decimal',
      origem: 'frequency',
    });
  }

  let clicks = 0;
  if (ins.inline_link_clicks != null && ins.inline_link_clicks !== '') {
    clicks = parseFloat(ins.inline_link_clicks);
  } else if (ins.clicks != null && ins.clicks !== '') {
    clicks = parseFloat(ins.clicks);
  }
  if (clicks > 0) {
    addMetrica(metricas, vistos, {
      nome: 'Cliques nos Anúncios',
      valor: clicks,
      formato: 'numero',
      origem: 'clicks',
    });
  }

  if (impressions > 0 && spend > 0) {
    addMetrica(metricas, vistos, {
      nome: 'CPM',
      valor: Number(((spend / impressions) * 1000).toFixed(2)),
      formato: 'moeda',
      origem: 'cpm_calc',
    });
  }
  if (impressions > 0 && clicks > 0) {
    addMetrica(metricas, vistos, {
      nome: 'CTR',
      valor: Number(((clicks / impressions) * 100).toFixed(2)),
      formato: 'percentual',
      origem: 'ctr_calc',
    });
  }

  const acoes = Array.isArray(ins.actions) ? ins.actions : [];
  for (const a of acoes) {
    const v = parseFloat(a.value || 0);
    if (v <= 0) continue;
    const tipo = a.action_type;
    if (['reach', 'impressions', 'spend'].includes(tipo)) continue;
    addMetrica(metricas, vistos, {
      nome: rotuloAcao(tipo),
      valor: v,
      formato: 'numero',
      origem: tipo,
    });
  }

  const custos = Array.isArray(ins.cost_per_action_type) ? ins.cost_per_action_type : [];
  for (const c of custos) {
    const v = parseFloat(c.value || 0);
    if (v <= 0) continue;
    const base = rotuloAcao(c.action_type);
    addMetrica(metricas, vistos, {
      nome: `Custo por ${base}`,
      valor: Number(v.toFixed(2)),
      formato: 'moeda',
      origem: `cost_${c.action_type}`,
    });
  }

  const valores = Array.isArray(ins.action_values) ? ins.action_values : [];
  for (const av of valores) {
    const v = parseFloat(av.value || 0);
    if (v <= 0) continue;
    const tipo = String(av.action_type || '');
    if (tipo.includes('purchase') || tipo === 'purchase') {
      addMetrica(metricas, vistos, {
        nome: 'Faturamento',
        valor: Number(v.toFixed(2)),
        formato: 'moeda',
        origem: av.action_type,
      });
    }
  }

  const vendas = metricas.find((m) => m.nome === 'Vendas');
  const faturamento = metricas.find((m) => m.nome === 'Faturamento');
  if (vendas && faturamento && vendas.valor > 0) {
    addMetrica(metricas, vistos, {
      nome: 'Ticket Médio',
      valor: Number((faturamento.valor / vendas.valor).toFixed(2)),
      formato: 'moeda',
      origem: 'ticket_medio_calc',
    });
    if (spend > 0) {
      addMetrica(metricas, vistos, {
        nome: 'Custo por Venda',
        valor: Number((spend / vendas.valor).toFixed(2)),
        formato: 'moeda',
        origem: 'custo_venda_calc',
      });
    }
  }

  return metricas;
}

function legadoDeMetricas(metricas) {
  const get = (nome) => metricas.find((m) => m.nome === nome)?.valor ?? 0;
  const spend = get('Valor investido');
  const reach = get('Pessoas Alcançadas');
  const impressions = get('Impressões');
  const clicks = get('Cliques nos Anúncios');
  const leads = get('Leads');
  const mensagens = get('Conversas no WhatsApp');
  const ctr = get('CTR');
  const cpm = get('CPM');
  const freq = get('Frequência');

  return {
    spend,
    reach,
    impressions,
    clicks,
    leads,
    mensagens,
    ctr: ctr || (impressions > 0 && clicks > 0 ? Number(((clicks / impressions) * 100).toFixed(2)) : 0),
    cpm: cpm || (impressions > 0 ? Number(((spend / impressions) * 1000).toFixed(2)) : 0),
    frequencia: freq || (reach > 0 ? Number((impressions / reach).toFixed(2)) : 0),
    custoLead: leads > 0 ? Number((spend / leads).toFixed(2)) : null,
    custoMensagem: mensagens > 0 ? Number((spend / mensagens).toFixed(2)) : null,
  };
}

const normalizados = insights.map((ins) => {
  const campaignId = ins.campaign_id != null ? String(ins.campaign_id) : null;
  const metricas = metricasDaInsight(ins);
  const leg = legadoDeMetricas(metricas);

  return {
    json: {
      campaign_id: campaignId,
      meta_campaign_id: campaignId,
      campanha: ins.campaign_name || ins.campaignName || 'Sem nome',
      metricas,
      ...leg,
    },
  };
});

return normalizados;

const listaSource = $('📋 Lista Destaque Odonto').first().json;
const res = $input.first().json;

const todas = Array.isArray(res.data) ? res.data : [];

function campanhaAtiva(c) {
  const st = String(c.effective_status || c.status || '').toUpperCase();
  return st === 'ACTIVE';
}

const campanhas = todas.filter(campanhaAtiva);
const body = listaSource.body || {};
const objetivoFiltro = body.objetivo_campanha || null;

const filtradas = objetivoFiltro
  ? campanhas.filter((c) => String(c.objective || '') === String(objetivoFiltro))
  : campanhas;

const idsFiltradas = filtradas
  .map((c) => (c.id != null ? String(c.id) : null))
  .filter(Boolean);

const objetivos_por_campanha = {};
for (const c of campanhas) {
  if (c?.id != null && c.objective) {
    objetivos_por_campanha[String(c.id)] = String(c.objective);
  }
}

const cliente = { ...listaSource.cliente, objetivos_por_campanha };

return [
  {
    json: {
      cliente,
      body,
      campaign_ids_filtradas: idsFiltradas,
      total_campanhas_ativas: campanhas.length,
      total_campanhas_conta: todas.length,
    },
  },
];

const ctx = $('Filtrar campanhas (objetivo)').first().json ?? {};
const idsFiltradas = ctx.campaign_ids_filtradas || [];
const idSet = new Set(idsFiltradas.map(String));

const rowsSource = $input.first()?.json;
let rows = [];
if (rowsSource && Array.isArray(rowsSource.data)) {
  rows = rowsSource.data;
}

if (idSet.size) {
  rows = rows.filter((r) => {
    const cid = r.campaign_id != null ? String(r.campaign_id) : null;
    return Boolean(cid && idSet.has(cid));
  });
}

function extrairMidiaCreative(creative) {
  if (!creative || typeof creative !== 'object') {
    return { image_url: '', thumbnail_url: '', video_id: null, tipo: 'outro' };
  }

  let image_url = creative.image_url || '';
  let video_id = creative.video_id || null;
  const spec = creative.object_story_spec || {};
  const link = spec.link_data || {};
  const video = spec.video_data || {};

  if (!image_url && link.picture) image_url = link.picture;
  if (!image_url && video.image_url) image_url = video.image_url;
  if (!video_id && video.video_id) video_id = video.video_id;

  let thumbnail_url = creative.thumbnail_url || '';
  if (!thumbnail_url && video.image_url) thumbnail_url = video.image_url;
  if (!thumbnail_url && link.picture) thumbnail_url = link.picture;
  if (!thumbnail_url && image_url) thumbnail_url = image_url;

  const tipo = video_id ? 'video' : image_url || thumbnail_url ? 'imagem' : 'outro';

  return { image_url, thumbnail_url, video_id, tipo };
}

const ads_por_campanha = {};
for (const r of rows) {
  const cid = r.campaign_id != null ? String(r.campaign_id) : null;
  if (!cid) continue;
  if (!ads_por_campanha[cid]) ads_por_campanha[cid] = [];

  const creative = r.creative || {};
  const midia = extrairMidiaCreative(creative);

  ads_por_campanha[cid].push({
    ad_id: String(r.id || ''),
    nome: r.name || creative.name || creative.title || 'Anúncio',
    name: r.name,
    status: r.effective_status || r.status || '',
    thumbnail_url: midia.thumbnail_url,
    image_url: midia.image_url,
    video_id: midia.video_id,
    tipo: midia.tipo,
  });
}

return [{ json: { ads_por_campanha } }];

const dados = $input.all().map((i) => i.json);

const prompt = `
Você é um analista sênior de Meta Ads.

Analise as campanhas e retorne APENAS JSON VÁLIDO (sem markdown).

Cada campanha em DADOS já traz "metricas": array com { nome, valor, formato } vindos da Meta.
NÃO invente métricas. NÃO remova métricas. NÃO renomeie métricas — use os mesmos "nome" de DADOS.
Pode acrescentar score, status, pontos_fortes, pontos_fracos, recomendacoes com base nos valores reais.

FORMATO:

{
  "kpis": {
    "metricas_resumo": [
      { "nome": string, "valor": number, "formato": "moeda" | "numero" | "percentual" | "decimal" }
    ],
    "melhor_campanha": string
  },
  "campanhas": [
    {
      "nome": string,
      "objetivo": string | null,
      "metricas": [ { "nome": string, "valor": number, "formato": string } ],
      "score": number,
      "status": "Excelente" | "Boa" | "Atenção" | "Crítica",
      "pontos_fortes": [string],
      "pontos_fracos": [string],
      "recomendacoes": [string],
      "criativos": [ { "nome": string, "ad_id": string, "thumbnail_url": string, "status": string } ]
    }
  ],
  "insights_gerais": [string],
  "acoes_recomendadas": [string]
}

REGRAS:
- metricas_resumo = soma/agregação lógica das metricas de todas as campanhas (mesmos nomes quando fizer sentido)
- Em cada campanha, copie o array "metricas" integralmente de DADOS
- MAXIMO 2 bullets em pontos_fortes, pontos_fracos, recomendacoes
- MAXIMO 3 itens em insights_gerais e acoes_recomendadas

DADOS:
${JSON.stringify(
  dados.map((d) => ({
    nome: d.nome || d.campanha,
    objetivo: d.objetivo,
    metricas: d.metricas || [],
    criativos: (d.criativos || []).map((c) => ({
      nome: c.nome,
      ad_id: c.ad_id,
      status: c.status,
      thumbnail_url: c.thumbnail_url,
    })),
  }))
)}
`;

return [
  {
    json: {
      claudeBody: {
        model: 'claude-sonnet-4-5-20250929',
        max_tokens: 8192,
        messages: [{ role: 'user', content: prompt }],
      },
    },
  },
];

const webhook = $('Webhook').first().json ?? {};
const bodyRaw = webhook.body ?? webhook ?? {};

const clienteBase = [
  {
    nome: 'Destaque Odonto',
    account_id: 'act_489210827505328',
    grupo_jid: '120363426291607702@g.us',
    filtro_campanha: null,
